def calc_discount(subtotal, level):
    """Return the discount amount for a subtotal at a member level."""
    rate = {"basic": 0.0, "silver": 0.05, "gold": 0.1}.get(level, 0.0)
    return round(subtotal * rate, 2)


def calc_discount_rate(level):
    return {"basic": 0.0, "silver": 0.05, "gold": 0.1}.get(level, 0.0)

